window.__texto({"id": "732885810", "paragrafos": [{"c": "identifica", "t": "CONSULTA PÚBLICA Nº 17, DE 17 DE SETEMBRO DE 2026"}, {"c": "ementa", "t": "Proposta de aperfeiçoamento do Regulamento para Inspeção Acreditada de Empreendimentos de Infraestrutura, aprovado pela Portaria nº 367, de 20 de dezembro de 2017."}, {"c": "dou-paragraph", "t": "O PRESIDENTE DO INSTITUTO NACIONAL DE METROLOGIA, QUALIDADE E TECNOLOGIA - Inmetro, no exercício da competência que lhe foi outorgada pelos artigos 4º, § 2º, da Lei nº 5.966, de 11 de dezembro de 1973, e 3º, incisos I e IV, da Lei nº 9.933, de 20 de dezembro de 1999, combinados com o disposto no artigo 18, inciso V, do Anexo I ao Decreto nº 11.221, de 5 de outubro de 2022, considerando o que consta no Processo SEI nº 0052600.007801/2025-05, resolve:"}, {"c": "dou-paragraph", "t": "Art. 1º Fica disponível, no sítio www.inmetro.gov.br, a proposta de texto de aperfeiçoamento do Regulamento para Inspeção Acreditada de Empreendimentos de Infraestrutura, aprovado pela Portaria nº 367, de 20 de dezembro de 2017."}, {"c": "dou-paragraph", "t": "Art. 2º Fica aberto, a partir da data da publicação desta Consulta Pública no Diário Oficial da União, o prazo de 60 (sessenta) dias para que sejam apresentadas sugestões e críticas relativas ao texto proposto."}, {"c": "dou-paragraph", "t": "Art. 3º As críticas e sugestões devem ser apresentadas no Portal Brasil Participativo, contido na página eletrônica: https://brasilparticipativo.presidencia.gov.br/"}, {"c": "dou-paragraph", "t": "§ 1º As críticas e sugestões que não forem apresentadas conforme previsto no caput não serão consideradas como válidas para efeito da consulta pública e serão devolvidas ao demandante."}, {"c": "dou-paragraph", "t": "§ 2º O demandante que tiver dificuldade em utilizar o Portal poderá solicitar ajuda através dos canais de atendimento do Inmetro, disponíveis na página eletrônica: https://www.gov.br/inmetro/pt-br/canais_atendimento/ouvidoria/faca-sua-manifestacao."}, {"c": "dou-paragraph", "t": "Art. 4º Findo o prazo fixado no art. 2º desta Portaria, o Inmetro se articulará com as entidades que tenham manifestado interesse na matéria, para que indiquem representantes nas discussões posteriores, visando à consolidação do texto final."}, {"c": "dou-paragraph", "t": "Art. 5º Esta Consulta Pública entra em vigor na data de sua publicação no Diário Oficial da União."}, {"c": "assina", "t": "MARCIO ANDRE OLIVEIRA BRITO"}, {"c": "dou-paragraph", "t": "ANEXO"}, {"c": "dou-paragraph", "t": "PORTARIA INMETRO Nº XXX, DE xx DE xxxxxxx DE 2026"}, {"c": "dou-paragraph", "t": "Aprova os Requisitos de Avaliação da Conformidade para Inspeção de Empreendimentos de Infraestrutura - Consolidado."}, {"c": "dou-paragraph", "t": "O PRESIDENTE DO INSTITUTO NACIONAL DE METROLOGIA, QUALIDADE E TECNOLOGIA - INMETRO, no exercício da competência que lhe foi outorgada pelos artigos 4º, § 2º, da Lei nº 5.966, de 11 de dezembro de 1973, e 3º, incisos I e IV, da Lei nº 9.933, de 20 de dezembro de 1999, combinados com o disposto no artigo 18, inciso V, do Anexo I ao Decreto nº 11.221, de 5 de outubro de 2022, considerando o Acordo de Cooperação Técnica nº 8, entre a Secretaria Especial do Programa de Parcerias de Investimentos - SPPI e o INMETRO, visando à implantação da política de inspeção de projetos e de obras, cujo extrato foi publicado no Diário Oficial da União em 2 de junho de 2017, e o que consta no Processo SEI nº 0052600.007801/2025-05, resolve:"}, {"c": "dou-paragraph", "t": "Objeto e âmbito de aplicação"}, {"c": "dou-paragraph", "t": "Art. 1º Ficam aprovados os Requisitos de Avaliação da Conformidade para Inspeção de Empreendimentos de Infraestrutura, fixados no Anexo I desta Portaria."}, {"c": "dou-paragraph", "t": "Art. 2º A avaliação da conformidade dos empreendimentos de infraestrutura, de caráter voluntário, por meio do mecanismo de inspeção, deve ser realizada por Organismo de Inspeção Acreditado de Empreendimentos de Infraestrutura Tipo A ou não /A, estabelecido no Brasil e acreditado pelo Inmetro, consoante os Requisitos ora aprovados."}, {"c": "dou-paragraph", "t": "§ 1º Aplicam-se os presentes Requisitos aos:"}, {"c": "dou-paragraph", "t": "I - projetos de empreendimentos de infraestrutura;"}, {"c": "dou-paragraph", "t": "II - obras de empreendimentos de infraestrutura; e"}, {"c": "dou-paragraph", "t": "III - operação e desempenho de empreendimentos de infraestrutura."}, {"c": "dou-paragraph", "t": "§ 2º Para efeitos desta Portaria, são empreendimentos de infraestrutura: aeroportos, ferrovias/metrôs, rodovias, portos, geração hidrelétrica, distribuição de energia, transmissão de energia, mineração, exploração de óleo e gás, iluminação pública, habitacionais/edificações e saneamento."}, {"c": "dou-paragraph", "t": "Art. 3º Não compete ao Inmetro o exercício do poder de polícia administrativa quanto ao objeto, cabendo, exclusivamente, a supervisão quanto ao uso da marca, tendo por foco o cumprimento das regras de Avaliação da Conformidade."}, {"c": "dou-paragraph", "t": "Prazos e disposições transitórias"}, {"c": "dou-paragraph", "t": "Art. 4º As inspeções de empreendimentos de infraestrutura iniciadas e não finalizadas até a data de vigência desta Portaria, poderão ser concluídas ainda com base na Portaria Inmetro nº 367, de 2017."}, {"c": "dou-paragraph", "t": "Cláusula de revogação"}, {"c": "dou-paragraph", "t": "Art. 5º Ficam revogadas, no prazo de 6 (seis) meses, contados da data de vigência desta Portaria as Portarias Inmetro:"}, {"c": "dou-paragraph", "t": "I - nº 367, de 20 de dezembro de 2017, publicada no Diário Oficial da União de 21 de dezembro de 2017, seção 1, página 172; e"}, {"c": "dou-paragraph", "t": "II - nº 39, de 6 de fevereiro de 2020, publicada no Diário Oficial da União de 11 de fevereiro de 2020, seção 1, página 36."}, {"c": "dou-paragraph", "t": "Vigência"}, {"c": "dou-paragraph", "t": "Art. 6º Esta Portaria entra em vigor na data de sua publicação no Diário Oficial da União."}, {"c": "dou-paragraph", "t": "MÁRCIO ANDRÉ OLIVEIRA BRITO"}, {"c": "dou-paragraph", "t": "ANEXO I - REQUISITOS DE AVALIAÇÃO DA CONFORMIDADE PARA INSPEÇÃO DE EMPREENDIMENTOS DE INFRAESTRUTURA"}, {"c": "dou-paragraph", "t": "1. OBJETIVO"}, {"c": "dou-paragraph", "t": "Estabelecer critérios e procedimentos de avaliação da conformidade para inspeção de empreendimentos de infraestrutura, visando assegurar a conformidade dos projetos, da execução, operação e desempenho das obras, quanto aos aspectos técnicos de engenharia, meio ambiente, gestão de riscos, industriais, contratuais, legais e econômico-financeiros, frente aos termos de referência ou editais aplicáveis."}, {"c": "dou-paragraph", "t": "Nota: Para simplicidade do texto desta Portaria, os \"Organismos de Inspeção Acreditados para Empreendimentos de Infraestrutura - OIA - EI\", serão denominados como \"OIA\"."}, {"c": "dou-paragraph", "t": "2. SIGLAS"}, {"c": "dou-paragraph", "t": "Para fins deste RAC, são adotadas as siglas contidas nos documentos complementares citados no item 3, acrescentadas das que seguem:"}, {"c": "", "t": "EVTEA"}, {"c": "", "t": "Estudo de viabilidade técnica, econômica e ambiental"}, {"c": "", "t": "OIA"}, {"c": "", "t": "Organismo de Inspeção Acreditado"}, {"c": "", "t": "RAC"}, {"c": "", "t": "Requisitos de Avaliação da Conformidade"}, {"c": "dou-paragraph", "t": "3. DOCUMENTOS COMPLEMENTARES"}, {"c": "dou-paragraph", "t": "Para fins deste RAC, são adotados os seguintes documentos complementares:"}, {"c": "", "t": "ABNT NBR ISO/IEC 17020"}, {"c": "", "t": "Avaliação da conformidade - Requisitos para o funcionamento de diferentes tipos de organismos que executam inspeção."}, {"c": "", "t": "Portaria Inmetro n° 248, de 2015, ou substitutiva"}, {"c": "", "t": "Aprova o Vocabulário Inmetro de Avaliação da Conformidade com termos e definições usualmente utilizados pela Diretoria de Avaliação da Conformidade do Inmetro."}, {"c": "", "t": "Portaria Inmetro nº 274, de 2014, ou substitutiva"}, {"c": "", "t": "Aprova o Regulamento para o Uso das Marcas, dos Símbolos, dos Selos e das Etiquetas do Inmetro. Portaria Inmetro n° 248, de 2015, ou substitutiva."}, {"c": "", "t": "ABNT NBR ISO/IEC 17000"}, {"c": "", "t": "Avaliação da conformidade - Vocabulário e princípios gerais"}, {"c": "dou-paragraph", "t": "3.2 Deve ser utilizada a versão atualizada das normas e documentos citados, cabendo ao OIA, quando aplicável, promover as adequações necessárias, a fim de possibilitar o uso da base normativa ou documento mais recentemente publicado."}, {"c": "dou-paragraph", "t": "3.3 O prazo para a adoção da versão mais atualizada da norma ou sua substitutiva é de 12 (doze) meses ou o prazo de adequação da própria norma, devendo ser adotado o maior desses 2 (dois) prazos."}, {"c": "dou-paragraph", "t": "4. DEFINIÇÕES"}, {"c": "dou-paragraph", "t": "Para fins deste RAC, são adotadas as definições a seguir, complementadas pelas definições contidas nos Documentos Complementares citados no item 3."}, {"c": "dou-paragraph", "t": "4.1 Abrangência da inspeção"}, {"c": "dou-paragraph", "t": "Extensão e conteúdo da avaliação a ser realizada durante a inspeção, compreendendo os aspectos e elementos que devem ser verificados."}, {"c": "dou-paragraph", "t": "4.2 Contratante"}, {"c": "dou-paragraph", "t": "Pessoa jurídica que estabelece contrato com o OIA para a realização da inspeção de empreendimentos de infraestrutura."}, {"c": "dou-paragraph", "t": "Nota: O contratante poderá estabelecer contrato com o OIA, independentemente de o demandante requerer a realização da inspeção acreditada."}, {"c": "dou-paragraph", "t": "4.3 Demandante"}, {"c": "dou-paragraph", "t": "Pessoa jurídica que toma a decisão e/ou determina como mandatória a realização da inspeção de empreendimentos de infraestrutura."}, {"c": "dou-paragraph", "t": "4.4 Etapa"}, {"c": "dou-paragraph", "t": "Fase específica em que o empreendimento de infraestrutura se encontra entre aqueles que são percorridos para a sua efetividade, desde os preliminares (elaboração de estudos, modelagem e projetos) até sua execução e operação."}, {"c": "dou-paragraph", "t": "4.5 Nível de projeto ou estudos"}, {"c": "dou-paragraph", "t": "Estágio de detalhamento das informações do projeto de engenharia e dos demais estudos técnicos do empreendimento, variando de acordo com os dados e elementos contidos na sua documentação, segundo as especificações contidas nas normas técnicas correlatas e, eventualmente, complementadas pelas exigências do Termo de Referência ou Edital utilizados para a contratação do projeto de engenharia ou estudo técnico em questão (exemplos - estudos preliminares, projeto básico, projeto executivo, as built)."}, {"c": "dou-paragraph", "t": "4.6 Operadora"}, {"c": "dou-paragraph", "t": "Pessoa jurídica que realiza a operação do empreendimento sendo responsável por seu desempenho, podendo ou não ser o contratante."}, {"c": "dou-paragraph", "t": "5. MECANISMO DE AVALIAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "O mecanismo de avaliação da conformidade para projetos de empreendimentos de infraestrutura, obras de empreendimentos de infraestrutura e operação e desempenho de empreendimentos de infraestrutura é a Inspeção."}, {"c": "dou-paragraph", "t": "6. REQUISITOS GERAIS DE INSPEÇÃO"}, {"c": "dou-paragraph", "t": "6.1 Definição da abrangência da inspeção"}, {"c": "dou-paragraph", "t": "6.1.1 É de responsabilidade do Demandante definir, para cada empreendimento de infraestrutura, a abrangência da inspeção, os itens a serem inspecionados e os referenciais a serem adotados. O Demandante deverá estabelecer expressamente eventual aplicação parcial das atividades previstas neste RAC, indicando os requisitos não aplicáveis. Na ausência dessa definição, todos os requisitos e atividades estabelecidos neste RAC serão considerados aplicáveis. O Demandante poderá ainda complementar a abrangência da inspeção com requisitos ou atividades adicionais, de acordo com sua conveniência e necessidade."}, {"c": "dou-paragraph", "t": "Nota: Para os fins deste RAC, entende-se por referenciais as normas, os regulamentos e outros documentos aplicáveis à inspeção, identificados por sua versão, edição ou data de publicação, quando aplicável, bem como pela respectiva hierarquia quando houver mais de um documento aplicável."}, {"c": "dou-paragraph", "t": "6.1.1.1 Tais definições devem ser manifestadas formalmente através de documento oficial emitido pelo Demandante."}, {"c": "dou-paragraph", "t": "6.1.1.2 As exclusões de abrangência da inspeção devem ser formalizadas pelo Demandante através de documentos oficiais e devidamente justificadas mediante uma análise de riscos, não se aplicando como solução para sanar não conformidades."}, {"c": "dou-paragraph", "t": "6.1.1.3 Antes do início das atividades de inspeção, a Contratante deverá disponibilizar ao OIA os documentos emitidos pelo Demandante contendo as informações e definições requeridas no item 6.1.1."}, {"c": "dou-paragraph", "t": "6.2 Solicitação da Inspeção"}, {"c": "dou-paragraph", "t": "6.2.1 O início do processo de inspeção está condicionado a uma manifestação formal do Contratante, que deve ser feita diretamente a um dos Organismos de Inspeção acreditados pela Cgcre/Inmetro, legalmente estabelecido no país. Previamente à contratação da inspeção, o Contratante deverá fornecer ao OIA, a documentação a seguir, para que o OIA possa proceder a uma análise crítica prévia, sem prejuízo de outras consideradas necessárias para a realização das atividades de inspeção pelo OIA."}, {"c": "dou-paragraph", "t": "6.2.2 São Documentos Gerais para a Inspeção de Estudos e Projetos, das Obras e da Operação do Empreendimento:"}, {"c": "dou-paragraph", "t": "a) edital e/ou Termo de Referência e seus anexos;"}, {"c": "dou-paragraph", "t": "b) contrato do empreendimento, com seus aditivos (ou minuta de contrato, caso este não tenha ainda sido emitido);"}, {"c": "dou-paragraph", "t": "c) documento formal do Demandante com a determinação da abrangência da inspeção, conforme subitem 6.1.1;"}, {"c": "dou-paragraph", "t": "d) para inspeção de projeto, quantitativo total (ou estimado, caso ainda não disponível quantitativo total) de documentos que compõem o projeto (exemplos - peças gráficas, estudos, memoriais descritivos, planilhas de cálculos, especificações técnicas);"}, {"c": "dou-paragraph", "t": "e) cronograma de elaboração dos projetos ou da execução das obras ou dos monitoramentos e do cumprimento dos requisitos contratuais da operação do empreendimento (ou etapas principais e duração estimada, caso este não tenha ainda sido emitido)."}, {"c": "dou-paragraph", "t": "6.2.3 São Documentos Complementares Específicos para Inspeção de Estudos e de Projetos do Empreendimento:"}, {"c": "dou-paragraph", "t": "a) lista de documentos dos estudos e projetos a serem inspecionados; e"}, {"c": "dou-paragraph", "t": "b) comentários ou ressalvas do Demandante em etapas anteriores."}, {"c": "dou-paragraph", "t": "6.2.4 São Documentos Complementares para Inspeção das Obras do Empreendimento:"}, {"c": "dou-paragraph", "t": "a) projeto executivo aprovado pelo Demandante, com seus Certificados de Inspeções e Relatórios de Inspeções (finais), se houver;"}, {"c": "dou-paragraph", "t": "b) planejamento da execução das obras e suas atualizações aprovadas pelo responsável técnico;"}, {"c": "dou-paragraph", "t": "c) ata de abertura do contrato de execução de obra ou documento similar;"}, {"c": "dou-paragraph", "t": "d) ordens de Serviço e eventuais relatórios de acompanhamento da obra;"}, {"c": "dou-paragraph", "t": "e) atas de eventuais suspensões e retomadas das obras;"}, {"c": "dou-paragraph", "t": "f) documento informando a conclusão das atividades;"}, {"c": "dou-paragraph", "t": "g) registros de ensaios de materiais;"}, {"c": "dou-paragraph", "t": "h) registros de execução das obras civis e de instalações;"}, {"c": "dou-paragraph", "t": "i) certificados de inspeções realizadas anteriormente;"}, {"c": "dou-paragraph", "t": "j) documentos complementares que demostrem a conformidade aos requisitos do projeto e demais requisitos técnicos estabelecidos;"}, {"c": "dou-paragraph", "t": "k) cronograma físico-financeiro da execução das obras;"}, {"c": "dou-paragraph", "t": "l) orçamento da execução das obras; e"}, {"c": "dou-paragraph", "t": "m) matriz de risco da obra."}, {"c": "dou-paragraph", "t": "6.2.5 São Documentos Complementares Específicos para Inspeção da Operação do Empreendimento:"}, {"c": "dou-paragraph", "t": "a) cronograma de monitoramento de indicadores de gestão da operação;"}, {"c": "dou-paragraph", "t": "b) cronograma de monitoramento dos parâmetros técnicos de desempenho da operação; e"}, {"c": "dou-paragraph", "t": "c) cronograma de atendimento dos requisitos contratuais gerais e de gestão de riscos referentes à operação."}, {"c": "dou-paragraph", "t": "6.2.6 A documentação prevista nos itens 6.2.2 a 6.2.5 deve estar integralmente de posse do OIA, em suas versões finais, previamente à elaboração do Plano de Inspeção."}, {"c": "dou-paragraph", "t": "6.3 Plano de inspeção"}, {"c": "dou-paragraph", "t": "6.3.1 O OIA deve possuir procedimento documentado para o planejamento e execução das inspeções, no qual devem estar descritos:"}, {"c": "dou-paragraph", "t": "a) os critérios para determinação dos aspectos técnicos, legais, regulamentares e contratuais, que atendam à abrangência da inspeção, aos itens a serem inspecionados e aos referenciais estabelecidos pelo Demandante, os quais devem ser inspecionados na sua totalidade."}, {"c": "dou-paragraph", "t": "a.1) especificamente para componentes de obras, cujos lotes sejam representados objetivamente por quantidades em unidades de itens, nos quais seja possível a aplicação da norma NBR 5426 - Planos de Amostragem e Procedimentos na Inspeção por Atributos (Nível II, Tabela 2 - Plano de Amostragem Simples Normal, NQA - 0,010), tal aplicação será permitida e deverá ser registrada pelo OIA para evidência;"}, {"c": "dou-paragraph", "t": "a.2) a inspeção por amostragem não é aplicável para as inspeções na fase de Estudos Preliminares e Projetos;"}, {"c": "dou-paragraph", "t": "a.3) A inspeção por amostragem para as inspeções na fase de Operação, para possível aplicação, deverá ser apresentada pela contratante e formalmente autorizada pelo Demandante;"}, {"c": "dou-paragraph", "t": "b) os métodos para avaliação prévia da disponibilidade de informações para estabelecimento do Plano de Inspeção e para a execução das inspeções; e"}, {"c": "dou-paragraph", "t": "c) os métodos para o registro das inspeções e respectiva comunicação com o Contratante sobre tratativas técnicas, resultados das inspeções, registro e tratamento de não conformidades."}, {"c": "dou-paragraph", "t": "6.3.2 Para cada processo objeto, um Plano de Inspeção deve ser emitido, contemplando todas as etapas até a emissão do(s) respectivo(s) Certificado(s) de Inspeção, que contenha:"}, {"c": "dou-paragraph", "t": "a) a listagem geral contendo todos os itens a serem inspecionados;"}, {"c": "dou-paragraph", "t": "b) a correlação dos itens a serem inspecionados, listados, com os respectivos referenciais e seus métodos de inspeção;"}, {"c": "dou-paragraph", "t": "c) a indicação da aplicação da inspeção na integralidade ou amostral e, no caso de amostral, indicar qual será a amostragem (rastreável ao documento que fundamenta sua aplicação);"}, {"c": "dou-paragraph", "t": "d) a equipe de inspeção indicando os nomes do Responsável Técnico, do Coordenador de Inspeção e a correlação dos nomes dos inspetores responsáveis para cada item a ser inspecionado; e"}, {"c": "dou-paragraph", "t": "e) o cronograma prévio das atividades de inspeção com os marcos de datas e seus entregáveis."}, {"c": "dou-paragraph", "t": "6.4 Planejamento das Inspeções de Campo (aplicável para inspeções de execução de obras e da operação)"}, {"c": "dou-paragraph", "t": "6.4.1 Uma vez avaliados os documentos obtidos e constatada sua completude, o OIA deve agendar a data da visita para as inspeções, informando ao responsável pela execução da obra / pela operação, que deve assegurar o acesso ao local de inspeção, em condições de segurança, e comunicar seus técnicos competentes e responsáveis, envolvidos com a atividade, para acompanhamento da inspeção."}, {"c": "dou-paragraph", "t": "6.4.2 Todas as inspeções realizadas pelo OIA devem obrigatoriamente contar com a participação de pessoal técnico designado pela empresa Contratante. Na ausência de pessoal técnico designado, a inspeção não será realizada e deverá ser reagendada."}, {"c": "dou-paragraph", "t": "6.4.3 O OIA deve determinar sob quais condições e restrições é possível fazer as inspeções e quais providências a Contratante deve tomar caso a inspeção seja inviável."}, {"c": "dou-paragraph", "t": "6.4.4 O OIA deve enviar comunicação formal à Contratante / Operadora a respeito da necessidade de extensão do prazo das atividades, com suas respectivas causas, indicando as medidas a serem adotadas para a conclusão das atividades de inspeção."}, {"c": "dou-paragraph", "t": "6.4.5 Para as inspeções das obras ou da operação (quando aplicável) o OIA deve fazer inspeções nos locais (inspeção de campo) para verificação, com a regularidade previamente planejada, ou de forma excepcional, se julgar necessária, para a verificação progressiva da execução das atividades, acompanhando, para o caso de obras, seu avanço físico."}, {"c": "dou-paragraph", "t": "6.4.6 No caso específico de inspeção de obras, é necessária a realização de inspeções durante a execução de todas as sequências construtivas de cada serviço a ser inspecionado, de acordo com o Plano de Inspeção, em especial nos casos em que essa inspeção seja impossível ou especialmente complexa após a execução do serviço."}, {"c": "dou-paragraph", "t": "6.4.7 A inspeção deve ser realizada mesmo no caso de atrasos dos trabalhos com relação ao planejamento."}, {"c": "dou-paragraph", "t": "7. INSPEÇÃO DE PROJETO DO EMPREENDIMENTO"}, {"c": "dou-paragraph", "t": "7.1 Abrangência da Inspeção de Projeto do Empreendimento"}, {"c": "dou-paragraph", "t": "7.1.1 A inspeção na etapa de Estudos Preliminares e de Projetos pode contemplar estudos técnicos diversos e projetos que precedam a etapa de execução de obras."}, {"c": "dou-paragraph", "t": "7.1.2 A inspeção nas etapas preliminares tem o objetivo de avaliar se os documentos técnicos foram elaborados em conformidade com as normas ou padrões técnicos aplicáveis, se possuem conteúdo e informações suficientes à sequência do seu desenvolvimento ou à execução das obras e se atendem os requisitos e critérios associados ao item avaliado. Devem ser considerados, obrigatoriamente, os requisitos exigidos no edital e/ou termo de referência, seus anexos, no contrato do empreendimento de infraestrutura e nas ressalvas por ventura exaradas nas análises previamente realizadas pelo Demandante sobre o projeto funcional ou anteprojeto que devem ser verificadas na etapa de inspeção de projetos."}, {"c": "dou-paragraph", "t": "7.1.3 A inspeção não se restringe à verificação qualitativa dos aspectos técnicos avaliados, mas, deve considerar também a coerência das informações entre os diversos documentos verificados."}, {"c": "dou-paragraph", "t": "7.1.4 A abrangência da inspeção de estudos preliminares e projeto, salvo determinação mais restrita ou ampliada pelo Demandante, deve incluir a avaliação:"}, {"c": "dou-paragraph", "t": "a) da completude dos documentos do projeto, ou seja, se há todos os elementos suficientes para a elaboração dos demais estudos necessários ou para a completa caracterização, execução e operação do empreendimento;"}, {"c": "dou-paragraph", "t": "b) do atendimento às normas e padrões técnicos aplicáveis à peça técnica inspecionada e, quando não for possível utilizar normas ou padrões em função da especificidade do caso concreto, deve ser feita a inspeção da fundamentação das justificativas e memoriais que demonstrem os critérios adotados, bem como, da anuência do Demandante;"}, {"c": "dou-paragraph", "t": "c) da compatibilidade entre os diversos documentos integrantes de um projeto ou estudo e da compatibilidade entre os diversos projetos ou estudos elaborados;"}, {"c": "dou-paragraph", "t": "d) da conformidade dos requisitos para a implantação da solução de projeto adotada, tendo em vista aspectos técnicos e socioambientais;"}, {"c": "dou-paragraph", "t": "e) do mapeamento dos riscos a que o projeto está sujeito e a definição de suas medidas de controle;"}, {"c": "dou-paragraph", "t": "f) da completude, detalhamento e exequibilidade do cronograma e seus elementos;"}, {"c": "dou-paragraph", "t": "g) dos aspectos relacionados à segurança dos trabalhadores e usuários;"}, {"c": "dou-paragraph", "t": "h) da correição do orçamento a ser investido na execução do empreendimento de infraestrutura, incluindo a indicação de um intervalo de incerteza do valor estimado;"}, {"c": "dou-paragraph", "t": "i) do atendimento à função e aos requisitos de desempenho previstos no edital e/ou termo de referência, seus anexos e contrato do empreendimento de infraestrutura;"}, {"c": "dou-paragraph", "t": "j) dos levantamentos e estudos de campo, laboratório e escritório necessários ao desenvolvimento dos estudos e projetos das etapas preliminares, considerando, quando for o caso, o acompanhamento monitorado da execução desses serviços; e"}, {"c": "dou-paragraph", "t": "k) da situação das licenças e autorizações ambientais e do cumprimento de suas condicionantes socioambientais associadas ao empreendimento."}, {"c": "dou-paragraph", "t": "7.1.5 A depender da natureza e da complexidade do empreendimento, o OIA poderá complementar a inspeção com critérios adicionais que considere necessários, com base em julgamento profissional e em requisitos gerais, visando garantir a segurança e a efetividade das etapas posteriores."}, {"c": "dou-paragraph", "t": "7.1.6 No caso de inspeções anteriores já realizadas, a próxima inspeção poderá concentrar-se apenas sobre os elementos modificados ou adicionados."}, {"c": "dou-paragraph", "t": "7.2 Critérios Gerais de Inspeção"}, {"c": "dou-paragraph", "t": "7.2.1 As inspeções são realizadas na documentação técnica, em qualquer fase, em relação ao nível dos estudos e projetos, abrangendo os seguintes aspectos de controle:"}, {"c": "dou-paragraph", "t": "a) confiabilidade"}, {"c": "dou-paragraph", "t": "a.1) verificação da aplicação de normas ou padrões técnicos de referência adotados na elaboração dos estudos e/ou projetos das etapas preliminares;"}, {"c": "dou-paragraph", "t": "a.2) verificação das justificativas e memoriais que demonstrem os critérios adotados, quando não for possível utilizar as normas ou padrões em função da especificidade do caso concreto; e"}, {"c": "dou-paragraph", "t": "a.3) verificação da suficiência e fundamentação dos estudos técnicos das etapas anteriores e da coerência das premissas dos documentos sob inspeção, podendo abranger no que for aplicável:"}, {"c": "dou-paragraph", "t": "a.3.1) estudos de demanda;"}, {"c": "dou-paragraph", "t": "a.3.2) estudos de mercado;"}, {"c": "dou-paragraph", "t": "a.3.3) EVTEA;"}, {"c": "dou-paragraph", "t": "a.3.4) avaliações econômico-financeiras;"}, {"c": "dou-paragraph", "t": "a.3.5) estudos de impactos ambientais;"}, {"c": "dou-paragraph", "t": "a.3.6) projetos e planos de gestão socioambiental;"}, {"c": "dou-paragraph", "t": "a.3.7) projetos de fornecimento e fabricação;"}, {"c": "dou-paragraph", "t": "a.3.8) planos de gestão de riscos;"}, {"c": "dou-paragraph", "t": "a.3.9) projetos de engenharia nos diversos níveis (anteprojeto, projeto básico, projeto executivo);"}, {"c": "dou-paragraph", "t": "a.3.10) orçamentos de obras; e"}, {"c": "dou-paragraph", "t": "a.3.11) cronograma de obras, entre outros identificados como necessários para atender as especificações do Demandante;"}, {"c": "dou-paragraph", "t": "b) completude e adequação"}, {"c": "dou-paragraph", "t": "b.1) verificação da correlação dos nomes dos autores que constam nos documentos com os nomes especificados para as suas verificações e aprovações e a confirmação das responsabilidades de cada profissional;"}, {"c": "dou-paragraph", "t": "b.2) verificação da completude dos documentos recebidos em relação a todas as entregas necessárias para o nível do estudo / projeto a ser inspecionado;"}, {"c": "dou-paragraph", "t": "b.3) verificação do atendimento ao quadro de requisitos;"}, {"c": "dou-paragraph", "t": "b.4) verificação da integridade das informações contidas em cada fase de evolução do empreendimento;"}, {"c": "dou-paragraph", "t": "b.5) verificação do atendimento de alterações das peças técnicas, inclusive quadro técnico, como resultado de uma inspeção anterior;"}, {"c": "dou-paragraph", "t": "b.6) verificação do atendimento às obrigações especificadas pelo Demandante (abrangência da inspeção, itens a serem inspecionados, referenciais a serem adotados, inclusões e exclusões); e"}, {"c": "dou-paragraph", "t": "b.7) verificação do atendimento às obrigações previstas no edital e/ou termo de referência, seus anexos e contrato do empreendimento de infraestrutura e das ressalvas por ventura exaradas, nas análises previamente realizadas pela Demandante sobre o projeto funcional ou anteprojeto, a serem verificadas na etapa de inspeção de projetos, quanto ao seu atendimento;"}, {"c": "dou-paragraph", "t": "c) legibilidade e consistência"}, {"c": "dou-paragraph", "t": "c.1) verificação da legibilidade dos documentos com relação ao uso da linguagem regulamentada / normatizada;"}, {"c": "dou-paragraph", "t": "c.2) verificação da clareza das informações dos documentos;"}, {"c": "dou-paragraph", "t": "c.3) verificação da confiabilidade dos cálculos efetuados; e"}, {"c": "dou-paragraph", "t": "c.4) verificação da coerência das informações entre os diversos documentos emitidos;"}, {"c": "dou-paragraph", "t": "d) compatibilidade"}, {"c": "dou-paragraph", "t": "d.1) verificação da compatibilidade dos estudos, projetos e demais documentos das disciplinas inspecionadas que se inter-relacionam;"}, {"c": "dou-paragraph", "t": "d.2) verificação da existência de documento oficial emitido pelo Demandante para o caso de autorização da Inspeção Acreditada e emissão de Certificado de Inspeção para disciplinas específicas;"}, {"c": "dou-paragraph", "t": "d.3) verificação da conformidade das soluções técnicas em relação aos requisitos expressos no Edital e/ou Termo de Referência, seus anexos, às especificações técnicas documentadas, outras legislações aplicáveis e ressalvas emitidas pelo Demandante, sobre análise do projeto funcional/anteprojeto; e"}, {"c": "dou-paragraph", "t": "d.4) verificação da conformidade das soluções técnicas em relação às normas de referência e quaisquer requisitos, para aspectos e impactos socioambientais, funcionalidade e uso, estabilidade das estruturas, topografia e fotogrametria, acessibilidade, segurança contra incêndio, metodologia de elaboração do cronograma e do orçamento, saúde e segurança ocupacional, segurança e organização do canteiro de obras."}, {"c": "dou-paragraph", "t": "7.3 Critérios Específicos de Inspeção"}, {"c": "dou-paragraph", "t": "7.3.1 Sem prejuízo de outros elementos que possam ser considerados necessários, e considerando a abrangência da inspeção não exaustiva anteriormente descrita neste RAC, os seguintes requisitos deverão ser avaliados, salvo se excluídos por determinação formal do Demandante, como integrantes das inspeções nos estudos e nos projetos (critérios específicos de inspeção):"}, {"c": "dou-paragraph", "t": "a) memoriais de cálculos"}, {"c": "dou-paragraph", "t": "a.1) verificação se as premissas e critérios adotados para os cálculos são consistentes com o resultado e com as normas e regulamentações aplicáveis;"}, {"c": "dou-paragraph", "t": "a.2) verificação se os dimensionamentos dos memoriais de cálculo foram realizados de forma completa, em relação ao nível do projeto inspecionado, e se os métodos de cálculo utilizados são detalhados, possibilitando serem interpretados de forma clara e inteligível;"}, {"c": "dou-paragraph", "t": "a.3) verificação da compatibilidade entre os resultados dos memoriais de cálculo, os desenhos e demais peças gráficas, requisitos de desempenho e especificações contratuais;"}, {"c": "dou-paragraph", "t": "a.4) verificação do dimensionamento dos elementos considerados críticos no projeto;"}, {"c": "dou-paragraph", "t": "a.5) verificação da compatibilidade e adequação dos desenhos e peças gráficas quanto ao previsto nos memoriais de cálculo, nas especificações técnicas, nas listas de quantidades, nos cálculos estruturais, nos levantamentos topográficos, nas investigações hidrológicas, geológicas e geotécnicas, bem como a identificação de eventuais interferências com outros projetos ou entre elementos do projeto elaborado;"}, {"c": "dou-paragraph", "t": "a.6) verificação do orçamento: deve verificar os itens a seguir, sendo atribuição do OIA definir um intervalo de valor considerado adequado para os investimentos de execução do empreendimento com seu respectivo intervalo de confiança, utilizando metodologia comparativa, expedita ou paramétrica, ou outra considerada mais adequada:"}, {"c": "dou-paragraph", "t": "a.6.1) se os custos adotados no resumo de cálculo das despesas são consistentes com a qualidade do serviço planejado e com a complexidade dos trabalhos necessários;"}, {"c": "dou-paragraph", "t": "a.6.2) qual a metodologia orçamentária aplicada para a estimativa do custo do empreendimento e se as técnicas orçamentárias estão adequadas à metodologia adotada;"}, {"c": "dou-paragraph", "t": "a.6.3) se no orçamento todos os elementos construtivos estão contemplados nas peças de custos e se os procedimentos de orçamentação adotados são corretos; e"}, {"c": "dou-paragraph", "t": "a.6.4) se há elementos suficientes para assegurar a adequação orçamentária dos itens críticos da execução do empreendimento, sob a perspectiva de quantidades, insumos e preços."}, {"c": "dou-paragraph", "t": "a.7) verificação dos cronogramas quanto a coerência e adequação entre o prazo total previsto para a execução do empreendimento e o tipo de infraestrutura a ser implantada por meio do projeto inspecionado, em função de sua complexidade, verificando ainda a completeza e integralidade das atividades previstas no cronograma;"}, {"c": "dou-paragraph", "t": "b) estudos de mercado e avaliações econômico-financeiras"}, {"c": "dou-paragraph", "t": "b.1) verificação da confiabilidade;"}, {"c": "dou-paragraph", "t": "b.2) verificação da adequação e consistência dos procedimentos adotados;"}, {"c": "dou-paragraph", "t": "b.3) verificação das fontes de informações;"}, {"c": "dou-paragraph", "t": "b.4) verificação das projeções financeiras e seus inputs;"}, {"c": "dou-paragraph", "t": "b.5) verificação das premissas; e"}, {"c": "dou-paragraph", "t": "b.6) verificação dos métodos de cálculo;"}, {"c": "dou-paragraph", "t": "c) aspectos socioambientais (avaliação de licenças e demais instrumentos regulatórios aprovados de modo a permitir o início da execução das obras ou o início da operação do empreendimento), incluindo:"}, {"c": "dou-paragraph", "t": "c.1) verificação dos projetos socioambientais; e"}, {"c": "dou-paragraph", "t": "c.2) verificação de registros e evidências do atendimento às condicionantes para a mitigação dos impactos socioambientais decorrentes da implantação da infraestrutura;"}, {"c": "dou-paragraph", "t": "d) gestão de riscos"}, {"c": "dou-paragraph", "t": "d.1) verificação da existência de estrutura e procedimentos para a gestão de riscos, considerando as técnicas e normas existentes para o assunto; e"}, {"c": "dou-paragraph", "t": "d.2) verificação da compatibilidade entre a análise de riscos e o plano de contratação de apólices de seguros para o empreendimento."}, {"c": "dou-paragraph", "t": "7.3.1.1 Havendo a necessidade da realização de inspeções não descritas ou detalhadas anteriormente, as verificações deverão ser consolidadas em Relatórios de Visitas, considerando os critérios já descritos e ainda as:"}, {"c": "dou-paragraph", "t": "a) especificações requeridas;"}, {"c": "dou-paragraph", "t": "b) regulamentações obrigatórias; e"}, {"c": "dou-paragraph", "t": "c) normas técnicas aplicáveis, inclusive no que diz respeito à integralidade da documentação do projeto."}, {"c": "dou-paragraph", "t": "8. INSPEÇÃO DA EXECUÇÃO DO EMPREENDIMENTO"}, {"c": "dou-paragraph", "t": "8.1 Abrangência da Inspeção da Execução do Empreendimento"}, {"c": "dou-paragraph", "t": "8.1.1 A inspeção na etapa de execução do empreendimento de infraestrutura tem o objetivo de garantir a compatibilidade entre as etapas de estudos e projetos com a de execução das obras, para o atendimento aos requisitos exigidos pelo Demandante, bem como visa mitigar riscos associados à qualidade da execução, à capacidade dos prestadores de serviço em concluírem suas entregas nos prazos e custos previstos, ao cumprimento do cronograma, à prática de preços descolados do mercado e aos usos e fontes de insumos para execução do empreendimento."}, {"c": "dou-paragraph", "t": "8.1.2 A abrangência da inspeção da execução da obra, salvo determinação mais restrita ou ampliada pelo Demandante, deve incluir:"}, {"c": "dou-paragraph", "t": "a) inspeção da execução da obra em conformidade com os projetos aprovados;"}, {"c": "dou-paragraph", "t": "b) inspeção dos custos e dos prazos realizados em relação ao orçamento e cronograma físico-financeiro aprovados;"}, {"c": "dou-paragraph", "t": "c) inspeção do atendimento dos requisitos estabelecidos pelo Demandante;"}, {"c": "dou-paragraph", "t": "d) inspeção dos procedimentos de desapropriação e de sua execução;"}, {"c": "dou-paragraph", "t": "e) inspeção do cumprimento das etapas do empreendimento;"}, {"c": "dou-paragraph", "t": "f) inspeção da situação das licenças e autorizações ambientais e dos registros e evidências de cumprimento das condicionantes requeridos pelo órgão licenciador;"}, {"c": "dou-paragraph", "t": "g) inspeção da aplicação dos planos de mitigação de riscos e suas ações aprovados nas etapas preliminares;"}, {"c": "dou-paragraph", "t": "h) inspeção dos procedimentos e dos resultados do controle da qualidade das obras; e"}, {"c": "dou-paragraph", "t": "i) inspeção das fontes dos insumos quanto à sua conformidade."}, {"c": "dou-paragraph", "t": "8.2 Avaliação Documental referente à Obra"}, {"c": "dou-paragraph", "t": "8.2.1 Cabe ao OIA comparar os dados reais, resultantes do processo de inspeção documental e de campo, com os dados de projeto e de modificações aprovadas, a fim de formular suas próprias considerações sobre o atendimento às especificações do projeto de empreendimento."}, {"c": "dou-paragraph", "t": "8.2.2 Com base no levantamento documental ou por circunstâncias fáticas, o OIA poderá determinar:"}, {"c": "dou-paragraph", "t": "a) se é possível considerar a inspeção realizada suficiente para a tomada de decisão da conformidade; ou"}, {"c": "dou-paragraph", "t": "b) providências a tomar caso o resultado da inspeção realizada não seja suficiente para a tomada de decisão."}, {"c": "dou-paragraph", "t": "8.3 Trabalhos não inspecionáveis"}, {"c": "dou-paragraph", "t": "8.3.1 Caso o OIA considere que os trabalhos não sejam inspecionáveis, deve registrar tal condição no Relatório de Inspeção, e solicitar a emissão de um relatório de ações por parte da Contratante, que deve indicar as alternativas possíveis (dentre as listadas a seguir) e respectivos prazos de execução, com as devidas justificativas técnicas:"}, {"c": "dou-paragraph", "t": "a) indicação de métodos alternativos para a avaliação da conformidade com os requisitos; e"}, {"c": "dou-paragraph", "t": "b) indicação de ações mitigadoras, com propostas para execução de sua validação."}, {"c": "dou-paragraph", "t": "8.3.2 O relatório de ações da Contratante deve ser apresentado ao OIA previamente à implementação das ações, para sua análise e aprovação."}, {"c": "dou-paragraph", "t": "8.3.3 O OIA deve avaliar a necessidade de efetuar uma nova inspeção para constatar a implementação das ações e sua eficácia."}, {"c": "dou-paragraph", "t": "8.3.4 Caso não seja possível adotar ações, o OIA deve registrar a impossibilidade da inspeção."}, {"c": "dou-paragraph", "t": "9. INSPEÇÃO DA OPERAÇÃO E DESEMPENHO DO EMPREENDIMENTO"}, {"c": "dou-paragraph", "t": "9.1 Abrangência da Inspeção da Operação e Desempenho do Empreendimento"}, {"c": "dou-paragraph", "t": "9.1.1 A inspeção na etapa de operação do empreendimento tem o objetivo de assegurar durante o período em que seja operado, que o monitoramento para demonstrar o atendimento aos requisitos exigidos pelo Demandante seja realizado pelo operador e inspecionado pelo OIA para avaliar a sua conformidade."}, {"c": "dou-paragraph", "t": "9.1.2 A abrangência da inspeção da operação e desempenho do empreendimento de infraestrutura, salvo determinação mais restrita ou ampliada pelo Demandante, deve incluir:"}, {"c": "dou-paragraph", "t": "a) os indicadores de gestão da operação - tem por finalidade verificar a conformidade - considerando:"}, {"c": "dou-paragraph", "t": "a.1) as fontes e a sistemática de coleta de dados para assegurar a sua integridade;"}, {"c": "dou-paragraph", "t": "a.2) a correta aplicação das fórmulas estabelecidas para os cálculos dos indicadores;"}, {"c": "dou-paragraph", "t": "a.3) a confirmação dos resultados apresentados; e"}, {"c": "dou-paragraph", "t": "a.4) a verificação do atendimento dos valores de referências estabelecidos."}, {"c": "dou-paragraph", "t": "Nota: Para indicadores qualitativos, que requeiram interpretação, devem ser considerados pelo OIA os critérios preestabelecidos pelo Demandante."}, {"c": "dou-paragraph", "t": "b) a inspeção dos parâmetros técnicos de desempenho - tem por finalidade verificar a conformidade -considerando:"}, {"c": "dou-paragraph", "t": "b.1) os parâmetros técnicos estabelecidos pelo Demandante que devem ser inspecionados;"}, {"c": "dou-paragraph", "t": "b.2) a correta aplicação das fórmulas estabelecidas para os cálculos dos indicadores;"}, {"c": "dou-paragraph", "t": "b.3) a confirmação dos resultados apresentados;"}, {"c": "dou-paragraph", "t": "b.4) o correto emprego do método requerido; e"}, {"c": "dou-paragraph", "t": "b.5) a utilização de equipamentos em estado adequado de conservação e calibrados em laboratórios acreditados, quando houver laboratório acreditado para a realização da calibração do equipamento;"}, {"c": "dou-paragraph", "t": "b.6) os casos em que o Demandante estabelecer; e"}, {"c": "dou-paragraph", "t": "b.7) a veracidade da informação resultante das medições e monitoramentos;"}, {"c": "dou-paragraph", "t": "c) a inspeção dos (demais) requisitos contratuais, a fim de avaliar se estão sendo atendidos pela contratante e/ou operadora;"}, {"c": "dou-paragraph", "t": "d) a inspeção da gestão dos riscos da operação que tem por finalidade avaliar se:"}, {"c": "dou-paragraph", "t": "d.1) os riscos existentes estão identificados;"}, {"c": "dou-paragraph", "t": "d.2) se são coerentes com a operação do empreendimento;"}, {"c": "dou-paragraph", "t": "d.3) se as medidas planejadas para prevenção e mitigação dos riscos são apropriadas e suficientes; e"}, {"c": "dou-paragraph", "t": "d.4) se as medidas estão implementadas e mantidas."}, {"c": "dou-paragraph", "t": "10. REGISTROS DE INSPEÇÃO"}, {"c": "dou-paragraph", "t": "10.1 Requisitos Gerais"}, {"c": "dou-paragraph", "t": "10.1.1 A inspeção deverá ser documentada através da elaboração de Listas de Verificações / Relatórios de Visitas / Relatórios Parciais durante as atividades de inspeção e Relatório de Inspeção ao final das atividades, consolidando as informações e evidências registradas pelo OIA."}, {"c": "dou-paragraph", "t": "10.1.2 Para fins de manutenção dos registros associados às inspeções, o OIA deve manter em seus arquivos os documentos referentes aos processos de inspeção, tais como os Planos de Inspeções, as Listas de Verificações, os Relatórios de Visitas, os Relatórios de Inspeções, o Certificado de Inspeção e demais documentos e registros de análises realizadas durante o processo."}, {"c": "dou-paragraph", "t": "10.1.3 Todos os documentos utilizados e produzidos no processo devem ser rastreáveis uns aos outros para demonstrar com transparência a sua realização."}, {"c": "dou-paragraph", "t": "10.1.4 O OIA deve demonstrar com clareza todas as atividades realizadas e as evidências de conformidade e não conformidade constatadas, o planejamento das atividades e sua realização, do início ao fim do processo."}, {"c": "dou-paragraph", "t": "10.1.5 Os documentos dos processos de inspeção deverão ser fornecidos pelo OIA ao Demandante e aos órgãos de controle, mediante solicitação formal, independentemente de quaisquer cláusulas contratuais de confidencialidade que porventura possam existir entre o Contratante e o OIA."}, {"c": "dou-paragraph", "t": "Nota: O Contratante será informado dessa ação."}, {"c": "dou-paragraph", "t": "10.2 Relatórios de Inspeção"}, {"c": "dou-paragraph", "t": "10.2.1 Relatório de Visita / Parcial"}, {"c": "dou-paragraph", "t": "10.2.1.1 Após cada visita de campo ou de conclusão de inspeção documental, é emitido um Relatório correspondente, denominado Relatório de Visita / Parcial, e enviado à Contratante."}, {"c": "dou-paragraph", "t": "10.2.1.2 Cada Relatório, além de uma breve descrição do objeto de inspeção, empreendimento e de sua localização, deve conter, no mínimo, as seguintes indicações:"}, {"c": "dou-paragraph", "t": "a) limites de abrangência da inspeção;"}, {"c": "dou-paragraph", "t": "b) data da visita de inspeção;"}, {"c": "dou-paragraph", "t": "c) assinaturas do responsável técnico e do inspetor do OIA e do profissional em nome do Contratante; e"}, {"c": "dou-paragraph", "t": "d) nomes e funções dos presentes nas inspeções (quando aplicável), bem como dos que não participaram, embora convidados."}, {"c": "dou-paragraph", "t": "10.2.1.3 O Relatório deve descrever, além do especificado anteriormente, os levantamentos efetuados pelo OIA, cada atividade e respectivas verificações efetuadas, o número e descrição dos ensaios realizados e os resultados obtidos. Os pontos de realização dos ensaios deverão ser indicados nos desenhos de projeto ou claramente individualizados no relatório."}, {"c": "dou-paragraph", "t": "10.2.1.4 Os relatórios devem ser emitidos em até (15) quinze dias após a data de cada visita ou após a emissão de relatórios de ensaios eventualmente requeridos, devendo incluir referência à conformidade das atividades e aos termos contratuais aplicáveis à abrangência da inspeção, sem que isto implique redução das responsabilidades da Contratante para as atividades de sua respectiva competência."}, {"c": "dou-paragraph", "t": "10.2.1.5 Estes relatórios são os documentos usados para consolidar as atividades de inspeção da completude, da adequação da documentação e para cada aspecto ou disciplina inspecionado descrevendo a conformidade ou a não conformidade com a abrangência da inspeção, itens a inspecionar e referenciais estabelecidos pelo Demandante, rastreáveis ao Plano de Inspeção, aos documentos de entrada, às respectivas Listas de Verificação e às suas evidências."}, {"c": "dou-paragraph", "t": "10.2.1.6 As não conformidades apontadas podem ser descritas e tratadas diretamente nos Relatórios de Visita/Parcial ou em Relatório específico para o tratamento de não conformidade, desde que referenciado no Relatório de Visita/Parcial e devidamente rastreável no processo."}, {"c": "dou-paragraph", "t": "10.2.1.7 As não conformidades devem descritas no momento em que forem identificadas e registradas em documento conforme apropriado."}, {"c": "dou-paragraph", "t": "10.2.2 Relatório de Inspeção Final"}, {"c": "dou-paragraph", "t": "10.2.2.1 O Relatório de Inspeção é o documento emitido após a conclusão das atividades de inspeção usado para consolidar as informações do processo completo no qual é apresentada a conclusão como \"Conforme\" ou \"Não Conforme\", sendo que, ao ser emitido com a conclusão \"Conforme\" indica que todas as atividades previstas no Plano de Inspeção foram concluídas e que, toda e qualquer não conformidade apontada tenha sido satisfatoriamente tratada e eliminada, permitindo, nesta situação, que seja emitido o Certificado de Inspeção."}, {"c": "dou-paragraph", "t": "10.2.2.2 Em caso de a exigência da inspeção do empreendimento constar do contrato de concessão ou privado os Relatórios de Inspeção poderão ser solicitados pelo ente público e/ou privado diretamente ao OIA sempre que julgado necessário."}, {"c": "dou-paragraph", "t": "10.2.2.3 A Contratante pode apresentar considerações sobre o Relatório de Inspeção em até 30 (trinta) dias úteis após sua emissão, desde que devidamente documentado."}, {"c": "dou-paragraph", "t": "10.2.2.4 O OIA deve avaliar as considerações da Contratante e apresentar resposta formal, indicando eventuais alterações aplicáveis."}, {"c": "dou-paragraph", "t": "11. TRATAMENTO DE NÃO CONFORMIDADES"}, {"c": "dou-paragraph", "t": "11.1 O OIA deve solicitar à Contratante a apresentação de um relatório contendo:"}, {"c": "dou-paragraph", "t": "a) proposta(s) e evidência(s) de ação(ões) de correção(ões);"}, {"c": "dou-paragraph", "t": "b) análise de causas da não conformidade;"}, {"c": "dou-paragraph", "t": "c) proposta(s) de ação(ões) corretiva(s);"}, {"c": "dou-paragraph", "t": "d) análise de abrangência e de impactos;"}, {"c": "dou-paragraph", "t": "e) ações para o caso de haver ocorrido ou ter o potencial de ocorrer em outros pontos dos estudos e/ou projetos ou obras ou operação; e"}, {"c": "dou-paragraph", "t": "f) prazos de execução das ações."}, {"c": "dou-paragraph", "t": "11.2 Tal Relatório, no caso de estudos preliminares e/ou projetos, deve conter a avaliação e aprovação dos projetistas responsáveis e ser apresentado ao OIA para análise e aprovação prévia à correção da falha identificada."}, {"c": "dou-paragraph", "t": "11.3 O OIA deve avaliar a necessidade de efetuar uma nova inspeção para constatar a implementação das correções e sua eficácia."}, {"c": "dou-paragraph", "t": "11.4 O OIA deve registrar a análise da eficácia das ações tomadas evidenciando a não recorrência da não conformidade."}, {"c": "dou-paragraph", "t": "11.5 Todo o processo de tratamento das não conformidades deve estar claramente descrito, com fácil acesso e recuperação das informações e devidamente rastreável em todo o processo de inspeção."}, {"c": "dou-paragraph", "t": "11.5.1 Durante o processo de inspeção no campo, o OIA deve notificar de maneira imediata ao Contratante quando da ocorrência de uma ou mais não conformidades. No caso de obra, o Contratante deve solicitar à Empreiteira, também a correção imediata do desvio, a fim de evitar que o erro se propague e agrave o problema objeto da não conformidade."}, {"c": "dou-paragraph", "t": "12. CERTIFICADO DE INSPEÇÃO"}, {"c": "dou-paragraph", "t": "12.1 O Certificado de Inspeção é emitido pelo OIA após o resultado conforme das inspeções planejadas e realizadas, sendo enviado à Contratante em até 30 (trinta) dias, ou prazo superior se previsto em contrato."}, {"c": "dou-paragraph", "t": "12.2 O Certificado de Inspeção não pode ser emitido caso alguma inspeção não tenha sido realizada ou caso existam não conformidades em aberto."}, {"c": "dou-paragraph", "t": "12.3 É admitida a emissão de Certificados de Inspeção em fases (lotes de projetos, trechos de obras, unidades construídas, parâmetros técnicos etc.), tendo em vista que as inspeções devem ocorrer obrigatoriamente nas diferentes fases de desenvolvimento e maturidade dos estudos e/ou projetos, fases de execução de obras ou fases da operação do empreendimento, em conformidade com o Plano de Inspeção."}, {"c": "dou-paragraph", "t": "12.4 Considerando a abrangência definida pelo Demandante, os Certificados de Inspeção não podem ser emitidos por disciplinas isoladas."}, {"c": "dou-paragraph", "t": "12.5 O Certificado de Inspeção deve apresentar, no caso de projetos e de documentos, a lista com suas identificações e suas versões consideradas conformes e que estarão representadas pelo Certificado de Inspeção emitido. Uma opção é a lista destes documentos, contendo todas estas informações, seja apresentada no Relatório de Inspeção permitindo a imediata rastreabilidade e confirmação das versões consideradas conformes."}, {"c": "dou-paragraph", "t": "12.6 As exclusões exigidas pelo Demandante, se existentes, devem constar no Certificado de Inspeção."}, {"c": "dou-paragraph", "t": "12.7 A Contratante pode apresentar considerações sobre o Certificado de Inspeção em até 30 (trinta) dias após sua emissão, desde que devidamente documentadas."}, {"c": "dou-paragraph", "t": "12.7.1 O OIA deve avaliar as considerações da Contratante e apresentar resposta formal, indicando eventuais alterações aplicáveis."}, {"c": "dou-paragraph", "t": "12.8 O OIA deve disponibilizar em seu website todos os Certificados de Inspeção emitidos, inclusive aqueles emitidos em fases."}, {"c": "dou-paragraph", "t": "13. DENÚNCIAS, RECLAMAÇÕES E SUGESTÕES"}, {"c": "dou-paragraph", "t": "A Ouvidoria do Inmetro recebe denúncias, reclamações e sugestões, através dos seguintes canais:"}, {"c": "dou-paragraph", "t": "- sítio: https://www.gov.br/inmetro/pt-br/canais_atendimento/ouvidoria; e"}, {"c": "dou-paragraph", "t": "- telefone: 0800 285 18 18."}]});